<?php
namespace App\Http\Controllers; use App\Models\{Product,Supplier,StockMovement}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ProductController extends Controller {public function index(Request $r){$q=Product::with('supplier');if($r->filled('search'))$q->where(fn($x)=>$x->where('name','like','%'.$r->search.'%')->orWhere('sku','like','%'.$r->search.'%'));if($r->boolean('low'))$q->whereColumn('quantity','<=','minimum_stock');return view('products.index',['products'=>$q->latest()->paginate(15)->withQueryString()]);}public function create(){return view('products.create',['suppliers'=>Supplier::orderBy('name')->get()]);}public function store(Request $r){$d=$r->validate(['supplier_id'=>'nullable|exists:suppliers,id','sku'=>'required|max:40|unique:products,sku','name'=>'required|max:160','description'=>'nullable|string','quantity'=>'required|integer|min:0','minimum_stock'=>'required|integer|min:0','unit_price'=>'required|numeric|min:0','location'=>'nullable|max:80']);DB::transaction(function()use($d){$p=Product::create($d);if($p->quantity>0)StockMovement::create(['product_id'=>$p->id,'user_id'=>auth()->id(),'type'=>'in','quantity'=>$p->quantity,'reason'=>'Stock initial']);});return redirect()->route('products.index')->with('success','Produit ajouté.');}}
